repo.ajouter({ id: 10, nom: "Disque SSD" });
try {
  repo.ajouter({ id: 10, nom: "Disque Doublon" });
} catch (e: any) {
  console.log("Doublon intercept\xE9 :", e.message);
}
console.log("Total apr\xE8s tentative :", repo.items().length);
